const D = { energy:.55, scale:1, hue:200, box:.5, antenna:.6, eyes:.5, arms:.5, base:.5, x:.5, y:.55, speed:1, density:.5, style:'retro', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const TAU=Math.PI*2, sty=P.style, en=P.energy, t=K.t;
const u=Math.min(width,height), sc=u*0.0034*P.scale, cx=P.x*width, cy=P.y*height;
const sway=0.9*Math.sin(t*0.53)+0.5*Math.sin(t*1.27+1.1)+0.3*Math.sin(t*2.11);
const hover=Math.sin(t*1.6)*0.5+Math.sin(t*0.9+2)*0.5;
const kick=K.pulse*0.4+A.bass*0.5;

let body=[P.hue,25,80], panel=[P.hue,35,55], metal=[P.hue,15,92], eyec=[(P.hue+160)%360,90,100], accent=[(P.hue+40)%360,80,95], ink=[P.hue,40,20], glowE=true;
if(sty==='mecha'){ body=[P.hue,30,58]; panel=[P.hue,40,38]; metal=[P.hue,20,72]; eyec=[15,90,100]; accent=[35,90,95]; ink=[P.hue,50,14]; }
else if(sty==='neon'){ body=[P.hue,20,25]; panel=[P.hue,30,18]; metal=[P.hue,25,40]; eyec=[(P.hue+120)%360,90,100]; accent=[(P.hue+300)%360,90,100]; ink=[(P.hue+120)%360,90,100]; }
else if(sty==='chrome'){ body=[210,8,88]; panel=[210,12,60]; metal=[210,6,99]; eyec=[190,80,100]; accent=[40,60,95]; ink=[210,20,30]; }
else if(sty==='pixel'){ body=[P.hue,35,78]; panel=[P.hue,45,50]; metal=[P.hue,20,90]; eyec=[120,80,95]; accent=[45,90,95]; ink=[P.hue,50,15]; glowE=false; }
function Cc(a,al){ return color(a[0],a[1],a[2],(al==null?100:al)*P.alpha/100); }
function box(x,y,w,h,r){ if(sty==='pixel') rect(x-w/2,y-h/2,w,h); else rect(x-w/2,y-h/2,w,h,r); }

push();
translate(cx, cy + hover*6*sc*(0.4+en));
rotate(sway*0.02);
scale(sc);
// shadow
noStroke(); fill(0,0,0,16); ellipse(0,120,150,20);

// base: legs / treads / hover
if(P.base<0.33){ // legs
  fill(Cc(panel,100)); box(-22,86,16,44,4); box(22,86,16,44,4);
  fill(Cc(metal,100)); box(-22,110,26,12,3); box(22,110,26,12,3);
} else if(P.base<0.66){ // treads
  fill(Cc(panel,100)); box(0,96,90,34,10);
  fill(Cc(ink,100)); for(let i=-3;i<=3;i++){ box(i*13,96,6,30,2); }
  fill(Cc(metal,100)); circle(-34,96,20); circle(34,96,20);
} else { // hover jet
  fill(Cc(accent, glowE?70:100)); if(glowE){drawingContext.shadowBlur=18;drawingContext.shadowColor=Cc(accent,90).toString();}
  triangle(-24,78, 24,78, 0,78+30+kick*10); drawingContext.shadowBlur=0;
}

// arms
const arm=Math.sin(t*1.9+1)*P.arms*0.4;
stroke(Cc(panel,100)); strokeWeight(9); strokeCap(ROUND);
push(); translate(-44,20); rotate(-0.3-arm); line(0,0,0,34); noStroke(); fill(Cc(metal,100)); circle(0,38,16); pop();
push(); translate(44,20); rotate(0.3+arm); line(0,0,0,34); noStroke(); fill(Cc(metal,100)); circle(0,38,16); pop();
noStroke();

// torso
const bw=76+P.box*24, bh=70;
fill(Cc(body,100)); box(0,26,bw,bh,10);
fill(Cc(metal,100)); box(0,26-bh/2+6,bw*0.9,8,3);   // collar
// chest panel with lights + gauge
fill(Cc(panel,100)); box(0,30,bw*0.62,bh*0.6,6);
for(let i=0;i<3;i++){ const on=(Math.sin(t*(2+i)+i*2)*0.5+0.5); fill(Cc([accent[0]+i*40,90,100], 40+on*60)); circle(-16+i*16, 18, 6); }
// gauge needle
push(); translate(0,40); stroke(Cc(ink,100)); strokeWeight(1.4); noFill(); arc(0,0,26,26,Math.PI,TAU);
rotate(Math.PI+ (Math.sin(t*0.8)*0.5+0.5)*Math.PI); stroke(Cc(eyec,100)); strokeWeight(2); line(0,0,10,0); pop(); noStroke();
// rivets
fill(Cc(ink,60)); for(const sx of [-1,1]) for(const sy of[-1,1]) circle(sx*bw*0.4, 26+sy*bh*0.38, 4);

// neck
fill(Cc(metal,100)); box(0,-14,14,14,2);

// head
const hw=54, hh=46;
fill(Cc(body,100)); box(0,-40,hw,hh,8);
fill(Cc(metal,100)); box(0,-40-hh/2+4,hw*0.8,6,2);
// eyes (visor or two)
const blink=((t*0.4+fr(2)*7)%3.0)<0.12?0.15:1;
if(P.eyes<0.5){ // visor
  fill(Cc(ink,100)); box(0,-42,hw*0.7,14,4);
  const scan=(Math.sin(t*1.5)*0.5+0.5);
  fill(Cc(eyec,100)); if(glowE){drawingContext.shadowBlur=14;drawingContext.shadowColor=Cc(eyec,90).toString();}
  rect(-hw*0.32+scan*hw*0.5, -46, 8, 8*blink, 2); drawingContext.shadowBlur=0;
} else { // two eyes
  for(const sx of [-1,1]){ fill(Cc(ink,100)); circle(sx*12,-42,16); fill(Cc(eyec,100));
    if(glowE){drawingContext.shadowBlur=12;drawingContext.shadowColor=Cc(eyec,90).toString();}
    circle(sx*12+ (P.x-0.5)*4,-42, 9*blink); drawingContext.shadowBlur=0; }
}
// mouth grille
stroke(Cc(ink,80)); strokeWeight(1.4); for(let i=-2;i<=2;i++) line(i*7,-24,i*7,-18); noStroke();
// antenna
if(P.antenna>0.05){ const aw=Math.sin(t*3+1)*P.antenna*0.5;
  stroke(Cc(metal,100)); strokeWeight(3); push(); translate(0,-40-hh/2); rotate(aw*0.3); line(0,0,0,-24*P.antenna);
  noStroke(); fill(Cc(accent,100)); if(glowE){drawingContext.shadowBlur=14;drawingContext.shadowColor=Cc(accent,90).toString();}
  circle(0,-24*P.antenna, 8+kick*4); drawingContext.shadowBlur=0; pop(); }
noStroke();
blendMode(BLEND); drawingContext.shadowBlur=0;
pop();
